    for (uint256 i = 0; i < config.length; i++) {
        IERC4626 id = config[i].id;
        if (!IEulerEarn(vault).config(id).enabled && (config[i].caps.maxIn > 0 || config[i].caps.maxOut > 0)) {
            revert ErrorsLib.MarketNotEnabled(id);
