        if (config[i].caps.maxIn > MAX_SETTABLE_FLOW_CAP || config[i].caps.maxOut > MAX_SETTABLE_FLOW_CAP) {
            revert ErrorsLib.MaxSettableFlowCapExceeded();
        }
        flowCaps[vault][id] = config[i].caps;
