```solidity
    function mint(uint256 _shares, address _receiver) external override returns (uint256 _assets) {
>>>     _processRewardsToPodLp(0, block.timestamp);
        _assets = convertToAssets(_shares);
        _deposit(_assets, _shares, _receiver);
